% NormImagefunction Result = NormImage(Object,mean1,ran1);[m n p]=size(Object);Object=Object(:);if nargin<1	help NormImage;	return;elseif nargin==1	min1=min(Object);	max1=max(Object);	multiplier=255.0/(max1-min1);	Result=(Object-min1).*multiplier;elseif (nargin>1)	if nargin==2		ran1=127;	end	imT=Object-mean(Object);	scalar=max(abs(imT));	Result=mean1+ran1.*(imT./scalar);end	Result=reshape(Result,[m,n,p]);